using System.Text.Json;
using System.Text.Json.Serialization;
namespace LeoLauncher;
sealed record UsageProfile
{
    public string Format{get;init;}="leo-profile-1";
    public string Id{get;init;}=Guid.NewGuid().ToString("N");public string Name{get;init;}="我的方案";
    public Dictionary<string,bool> Modules{get;init;}=new();
    public Dictionary<string,string> Entries{get;init;}=new();public List<string> Order{get;init;}=[];
    public bool IndexApplications{get;init;}=true;public bool Context{get;init;}=true;public bool Clipboard{get;init;}=true;public bool Updates{get;init;}=true;
    public Keys NoteKey{get;init;}=Keys.None;
    public Keys SearchKey{get;init;}=Keys.Control|Keys.Alt|Keys.Space;public Keys VoiceKey{get;init;}=Keys.None;public Keys LyricsKey{get;init;}=Keys.None;
}
static class UsageProfiles
{
    public static readonly string[] Builtins=["terminal","clash","music","edge","football","media"];
    internal static IEnumerable<OptionalEntry> ConfiguredEntries(Preferences p)=>EntryContributions.ReadBuiltins(p).Select(e=>new OptionalEntry(e.Id,e.SettingsName,e.Enabled,e.Hint)).Concat((p.ApplicationModules??[]).Select(a=>new OptionalEntry(a.Id,a.Name,a.Enabled,"")));
    public static UsageProfile Capture(Preferences p,string name,ExtensionStore? extensions=null)=>new(){Name=Name(name),Modules=ConfiguredEntries(p).Select(e=>new KeyValuePair<string,bool>(e.Id,e.Enabled)).Concat((extensions??new ExtensionStore(Path.Combine(Store.Root,"modules"))).Load().Select(m=>new KeyValuePair<string,bool>("ext:"+m.Id,!p.DisabledExtensions.Contains(m.Id)))).ToDictionary(e=>e.Key,e=>e.Value),Entries=new(p.EntryDisplayModes),Order=p.ShortcutOrder.Where(k=>k!=null&&EntryDisplay.ValidKey(k)).ToList(),IndexApplications=p.ApplicationIndexing,Context=p.ContextAware,Clipboard=p.ClipboardHistory,Updates=p.AutoUpdateNotifications,NoteKey=p.QuickNoteHotkey,SearchKey=p.SearchHotkey,VoiceKey=p.VoiceHotkey,LyricsKey=p.LyricsHotkey};
    public static string Name(string? name){name=(name??"").Trim();if(name.Length is <1 or >24||name.Any(char.IsControl))throw new ArgumentException("方案名称须为1～24个字符。");return name;}
    public static UsageProfile[] Templates()=>new[]{Template("companion","桌宠陪伴",[],false),Template("efficiency","效率桌面",["edge","media"],true),Template("geek","极客控制",["terminal","clash","edge","media"],true),Template("football","看球娱乐",["football","music","edge","media"],true)};
    static UsageProfile Template(string id,string name,string[] enabled,bool index)=>new(){Id="template:"+id,Name=name,Modules=Builtins.ToDictionary(k=>k,k=>enabled.Contains(k)),IndexApplications=index,Context=index,Clipboard=index,Updates=index,NoteKey=index?Keys.Control|Keys.Alt|Keys.N:Keys.None,SearchKey=index?Keys.Control|Keys.Alt|Keys.Space:Keys.None};
    public static void Validate(UsageProfile p){if(p.Format!="leo-profile-1"||string.IsNullOrWhiteSpace(p.Id)||p.Id.Length>80||!System.Text.RegularExpressions.Regex.IsMatch(p.Id,@"^[A-Za-z0-9:_-]+$"))throw new ArgumentException("不支持的方案格式。");Name(p.Name);if(p.Modules==null||p.Modules.Count>512||p.Modules.Keys.Any(k=>k.Length is <1 or >100||!System.Text.RegularExpressions.Regex.IsMatch(k,@"^[A-Za-z0-9:_-]+$")))throw new ArgumentException("方案模块列表无效。");EntryDisplay.Validate(p.Entries);if(p.Order==null||p.Order.Count>512||p.Order.Any(k=>k==null||!EntryDisplay.ValidKey(k)))throw new ArgumentException("快捷顺序无效。");LeoHotkeys.Validate([p.SearchKey,p.VoiceKey,p.LyricsKey,p.NoteKey]);}
    public static Preferences Prepare(UsageProfile profile,Preferences current,ExtensionStore? extensions=null){Validate(profile);var next=LocalApplications.Clone(current);foreach(string id in Builtins){bool enabled=profile.Modules.GetValueOrDefault(id);if(id=="football")next.FootballModule=enabled;else LocalApplications.SetEnabled(next,id,enabled);}next.ApplicationModules=next.ApplicationModules.Select(a=>a with{Enabled=profile.Modules.GetValueOrDefault(a.Id)}).ToList();next.DisabledExtensions=(extensions??new ExtensionStore(Path.Combine(Store.Root,"modules"))).Load().Where(m=>!profile.Modules.GetValueOrDefault("ext:"+m.Id)).Select(m=>m.Id).ToList();next.ApplicationIndexing=profile.IndexApplications;next.ContextAware=profile.Context;next.ClipboardHistory=profile.Clipboard;next.AutoUpdateNotifications=profile.Updates;next.QuickNoteHotkey=profile.NoteKey;next.SearchHotkey=profile.SearchKey;next.VoiceHotkey=profile.VoiceKey;next.LyricsHotkey=profile.LyricsKey;next.EntryDisplayModes=new(profile.Entries);next.ShortcutOrder=profile.Order.ToList();next.ActiveProfile=profile.Id;return next;}
    public static string Describe(UsageProfile profile,Preferences current){var next=Prepare(profile,current);var lines=new List<string>{"将切换到："+profile.Name,""};foreach(var entry in ConfiguredEntries(current)){bool enabled=profile.Modules.GetValueOrDefault(entry.Id);lines.Add(entry.Name+"："+(enabled?"开启":"停用")+(entry.Enabled!=enabled?"  ← 变更":""));}foreach(var item in new[]{("应用索引",profile.IndexApplications),("上下文观察",profile.Context),("剪贴板记录",profile.Clipboard),("自动更新提醒",profile.Updates)})lines.Add(item.Item1+"："+(item.Item2?"开启":"关闭"));lines.Add("搜索快捷键："+LeoHotkeys.Display(next.SearchHotkey));lines.Add("语音快捷键："+LeoHotkeys.Display(next.VoiceHotkey));lines.Add("歌词快捷键："+LeoHotkeys.Display(next.LyricsHotkey));lines.Add("速记快捷键："+LeoHotkeys.Display(next.QuickNoteHotkey));var extensions=new ExtensionStore(Path.Combine(Store.Root,"modules")).Load();foreach(var extension in extensions)lines.Add(extension.Name+"："+(profile.Modules.GetValueOrDefault("ext:"+extension.Id)?"开启":"停用"));var available=ConfiguredEntries(current).Select(e=>e.Id).Concat(extensions.Select(m=>"ext:"+m.Id)).ToHashSet();foreach(var unknown in profile.Modules.Keys.Where(k=>!available.Contains(k)))lines.Add("未匹配的模块："+unknown+"（忽略，不安装、不启动）");foreach(var dependency in ModuleStatuses.Read(next).Where(m=>m.State is ModuleState.NotInstalled or ModuleState.Invalid))lines.Add("需要处理："+dependency.Name+" · "+dependency.Label+"（设置 → 功能 → 模块状态与处理）");lines.Add("\n保留清单、便签、收藏、皮肤、API配置和本机程序路径。\n不会关闭外部软件、代理或媒体。方案不会自动执行组合动作。\n缺少依赖的软件可在模块状态页配置。模板默认停用独立扩展；自定义方案保留记录的扩展开关。");return string.Join("\n",lines).Replace("\n",Environment.NewLine);}
    public static string Serialize(UsageProfile p){Validate(p);return JsonSerializer.Serialize(p,new JsonSerializerOptions{WriteIndented=true});}
    public static UsageProfile Import(string file){if(new FileInfo(file).Length>128000)throw new ArgumentException("方案文件最多128KB。");var p=JsonSerializer.Deserialize<UsageProfile>(File.ReadAllText(file),new JsonSerializerOptions{UnmappedMemberHandling=JsonUnmappedMemberHandling.Disallow})??throw new ArgumentException("方案为空。");Validate(p);return p with{Id=Guid.NewGuid().ToString("N")};}
}
static class ProfileTransition
{
    public static void Apply(Preferences current,Preferences next,Action<Preferences> apply){var previous=LocalApplications.Clone(current);try{apply(next);}catch(Exception original){try{apply(previous);}catch(Exception rollback){throw new IOException("方案切换失败，恢复原配置也未完成，请重新打开设置检查。",new AggregateException(original,rollback));}throw;}}
}
sealed class ProfileStore
{
    readonly string? file;public List<UsageProfile> Items{get;private set;}=[];public string? Error{get;private set;}
    public ProfileStore(string? path){file=path;try{if(path!=null&&File.Exists(path)){Items=JsonSerializer.Deserialize<List<UsageProfile>>(File.ReadAllText(path))??[];if(Items.Count>50)throw new IOException("方案数量超限");foreach(var p in Items)UsageProfiles.Validate(p);}}catch{Items=[];Error="方案文件无法读取，原文件保留；请修复或备份后再管理方案。";}}
    public void Save(UsageProfile profile){UsageProfiles.Validate(profile);if(Error!=null)throw new IOException(Error);var next=Items.Where(p=>p.Id!=profile.Id).Append(profile).ToList();if(next.Count>50)throw new ArgumentException("最多保存50个方案。");Write(next);}
    public void Delete(string id){if(Error!=null)throw new IOException(Error);Write(Items.Where(p=>p.Id!=id).ToList());}
    void Write(List<UsageProfile> next){if(file!=null)ConfigMigration.Write(file,JsonSerializer.Serialize(next));Items=next;}
}
