}
sealed class UsageProfilesForm:BarcaWindow
{
    readonly ListBox list=new(){Bounds=new(24,110,245,350),BackColor=BarcaUi.Surface,ForeColor=BarcaUi.Text,BorderStyle=BorderStyle.None};readonly TextBox details=new(){Bounds=new(289,110,451,350),Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,BackColor=BarcaUi.Surface,ForeColor=BarcaUi.Text,BorderStyle=BorderStyle.None};readonly Label state=new(){Bounds=new(24,562,716,45),ForeColor=BarcaUi.Muted};readonly Preferences current;readonly ProfileStore store;readonly Action<Preferences> apply;
    UsageProfile? Selected=>list.SelectedItem is ComboChoice choice?UsageProfiles.Templates().Concat(store.Items).FirstOrDefault(p=>p.Id==choice.Value):null;
    public UsageProfilesForm(Preferences p,Action<Preferences> apply,bool preview=false){current=p;this.apply=apply;store=new(preview?null:Path.Combine(Store.Root,"leo-profiles.json"));Text="Leo · 使用方案";ClientSize=new(764,625);Controls.Add(BarcaUi.Chrome(this,"按你的习惯搭配 Leo","模板可混搭：先切换，再在设置里微调，另存为自己的方案。"));list.Font=BarcaUi.Font(10);list.DrawMode=DrawMode.OwnerDrawFixed;list.ItemHeight=37;list.DrawItem+=(_,e)=>{if(e.Index<0)return;using var brush=new SolidBrush((e.State&DrawItemState.Selected)!=0?BarcaUi.Raised:BarcaUi.Surface);e.Graphics.FillRectangle(brush,e.Bounds);TextRenderer.DrawText(e.Graphics,list.Items[e.Index].ToString(),list.Font,Rectangle.Inflate(e.Bounds,-8,0),BarcaUi.Text,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);};details.Font=BarcaUi.Font(10);list.SelectedIndexChanged+=(_,_)=>details.Text=Selected is {} selected?UsageProfiles.Describe(selected,current):"";var actions=new FlowLayoutPanel{Bounds=new(20,478,728,80)};void Button(string title,Action work){var b=new BarcaButton{Text=title,Size=new(132,32),Margin=new(4)};b.Click+=(_,_)=>{try{work();}catch(Exception e){state.Text=e.Message;}};actions.Controls.Add(b);if(title=="预览并切换")SelectionKeys.Wire(list,()=>b.PerformClick());}Button("预览并切换",()=>{if(Selected is not{} selected)return;using var review=new ProfileReviewForm(UsageProfiles.Describe(selected,current));review.StartPosition=FormStartPosition.CenterParent;if(review.ShowDialog(this)!=DialogResult.OK)return;var next=UsageProfiles.Prepare(selected,current);apply(next);state.Text="已切换："+selected.Name;});Button("另存当前配置",()=>{var name=Ask("保存当前方案","我的方案");if(name==null)return;var profile=UsageProfiles.Capture(current,name);store.Save(profile);Reload(profile.Id);});Button("重命名",()=>{if(Selected is not{} selected||selected.Id.StartsWith("template:"))throw new ArgumentException("模板保留原名，请另存为自定义方案。");var name=Ask("重命名方案",selected.Name);if(name==null)return;store.Save(selected with{Name=UsageProfiles.Name(name)});Reload(selected.Id);});Button("删除自定义",()=>{if(Selected is not{} selected||selected.Id.StartsWith("template:"))throw new ArgumentException("起始模板不能删除。");store.Delete(selected.Id);Reload();state.Text="方案已删除，当前功能配置和个人数据保留。";});Button("更新所选方案",()=>{if(Selected is not{} selected||selected.Id.StartsWith("template:"))throw new ArgumentException("模板不可覆盖，请先另存为自定义方案。");var profile=UsageProfiles.Capture(current,selected.Name) with{Id=selected.Id};store.Save(profile);Reload(profile.Id);state.Text="已用当前配置更新所选方案。";});Button("重置为模板",()=>{Reload("template:companion");state.Text="已选择桌宠陪伴模板，点击预览并切换后才生效。";});Button("导入方案",()=>{using var picker=new OpenFileDialog{Filter="Leo方案|*.json",CheckFileExists=true};if(picker.ShowDialog(this)!=DialogResult.OK)return;var profile=UsageProfiles.Import(picker.FileName);store.Save(profile);Reload(profile.Id);state.Text="已导入；请先预览并确认，导入不会执行程序。";});Button("导出选中方案",()=>{if(Selected is not{} selected)return;using var picker=new SaveFileDialog{Filter="Leo方案|*.json",FileName="Leo-profile.json"};if(picker.ShowDialog(this)==DialogResult.OK){ConfigMigration.Write(picker.FileName,UsageProfiles.Serialize(selected));state.Text="已导出能力和入口设置，不包含程序路径、Key及个人记录。";}});Controls.AddRange([list,details,actions,state]);Reload(current.ActiveProfile);if(store.Error!=null)state.Text=store.Error;MinimumSize=MaximumSize=Size;}
    string? Ask(string title,string initial){using var input=new QuickTextForm(title,initial,"只修改方案名称，不修改伙伴名字。");input.StartPosition=FormStartPosition.CenterParent;return input.ShowDialog(this)==DialogResult.OK?UsageProfiles.Name(input.Value):null;}
    void Reload(string? id=null){list.Items.Clear();foreach(var profile in UsageProfiles.Templates().Concat(store.Items))list.Items.Add(new ComboChoice(profile.Name+(profile.Id.StartsWith("template:")?" · 模板":""),profile.Id));list.SelectedItem=list.Items.Cast<ComboChoice>().FirstOrDefault(c=>c.Value==id)??list.Items[0];}
}

sealed partial class PetForm
